function [t] = convert_utc(y, mo, d, h, mi, s, dut1)
%CONVERT_UTC  timeconv.convertUTC: one UTC calendar instant in every scale, given UT1 - UTC [s] (the leap looked up once: the
%   same value MATLAB looks up in each of its calls).
%   y: real[1] (passed a plain number)
%   mo: real[1] (passed a plain number)
%   d: real[1] (passed a plain number)
%   h: real[1] (passed a plain number)
%   mi: real[1] (passed a plain number)
%   s: real[1] (passed a plain number)
%   dut1: real[1] (passed a plain number)
%   returns t: Times (passed rec)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    t = asils.models.timescales.Times_zero();
    jdu = asils.models.timescales.cal2jd(y, mo, d, h, mi, s);
    leap = asils.models.timescales.tai_minus_utc(jdu);
    tai_jd = (jdu + (leap / 86400));
    tt_jd = asils.models.timescales.tai2tt(tai_jd);
    tdb_jd = asils.models.timescales.tt2tdb(tt_jd);
    ut1_jd = asils.models.timescales.utc2ut1(jdu, dut1);
    gps_jd = asils.models.timescales.tai2gps(tai_jd);
    [week, sow] = asils.models.timescales.gps_week_sow(gps_jd);
    t = asils.models.timescales.Times_zero();
    t.utc_jd = jdu;
    t.tai_jd = tai_jd;
    t.tt_jd = tt_jd;
    t.tdb_jd = tdb_jd;
    t.ut1_jd = ut1_jd;
    t.gps_jd = gps_jd;
    t.utc_mjd = asils.models.timescales.jd2mjd(jdu);
    t.tt_mjd = asils.models.timescales.jd2mjd(tt_jd);
    t.tdb_mjd = asils.models.timescales.jd2mjd(tdb_jd);
    t.leap = leap;
    t.dut1 = dut1;
    t.t_tt = asils.models.timescales.tt2jc(tt_jd);
    t.j2000_tt_sec = asils.models.timescales.j2000sec(tt_jd);
    t.gps_week = week;
    t.gps_sow = sow;
    t.gmst_rad = asils.models.timescales.gmst82(ut1_jd);
    t.doy = asils.models.timescales.doy(y, mo, d);
end
